    IN_PROGRESS = 'IN_PROGRESS',
    COMPLETED = 'COMPLETED',
    ARCHIVED = 'ARCHIVED',
}

export function toSavedPostStatus(value: string): SavedPostStatus | undefined {
    const upper = value.toUpperCase();
    return Object.values(SavedPostStatus).find((status) => status === upper);
}

