305	    private Course loadCourseWithParticipationOfStudent(long courseId, long studentId) {
306	        Course course = courseLoadService.loadCourseWithExercisesLecturesLectureUnitsCompetenciesPrerequisitesAndExams(courseId);
307	        List<StudentParticipation> participations = studentParticipationRepository.findByStudentIdAndIndividualExercisesWithEagerLatestSubmissionsResultIgnoreTestRuns(studentId,
308	                course.getExercises());
309	
310	        Map<Long, Set<StudentParticipation>> participationMap = new HashMap<>();
311	        for (StudentParticipation participation : participations) {
312	            Long exerciseId = participation.getExercise().getId();
313	            participationMap.computeIfAbsent(exerciseId, k -> new HashSet<>()).add(participation);
314	        }
315	
316	        course.getExercises().forEach(exercise -> {
317	            Set<StudentParticipation> exerciseParticipations = participationMap.getOrDefault(exercise.getId(), Set.of());
318	            exercise.setStudentParticipations(exerciseParticipations);
319	        });
320	
321	        return course;
322	    }
